**第7步：生成配置文件**

根据收集的信息创建配置文件：
```bash
cat > {baseDir}/bilibili-monitor.json << 'EOF'
{
  "bilibili": {
    "cookies": "COOKIES值"
  },
  "ai": {
    "openrouter_key": "OPENROUTER_KEY值或空",
    "model": "MODEL值"
  },
  "email": {
    "smtp_email": "SMTP_EMAIL值",
    "smtp_password": "SMTP_PASSWORD值",
    "recipients": ["收件人1", "收件人2"]
  },
  "report": {"num_videos": 10}
}
EOF
```

配置文件仅包含非敏感设置：

```json
{
  "ai": {
    "model": "google/gemini-3-flash-preview"
  },
  "email": {
    "recipients": ["recipient@example.com"]
  },
  "report": {
    "num_videos": 10
  }
}
```

### 3. 设置环境变量

敏感凭据通过环境变量传递，不写入配置文件：

| 环境变量 | 说明 | 是否必须 |
|---------|------|---------|
| `BILIBILI_COOKIES` | 完整的B站 Cookie 字符串 | 是 |
| `OPENROUTER_API_KEY` | OpenRouter API Key（用于 AI 功能） | 可选 |
| `SMTP_EMAIL` | Gmail 发件邮箱 | 是（发邮件时） |
| `SMTP_PASSWORD` | Gmail 应用密码（16位） | 是（发邮件时） |

{
  "ai": {
    "model": "google/gemini-3-flash-preview"
  },
  "email": {
    "recipients": ["recipient1@example.com", "recipient2@example.com"]
  },
  "report": {
    "num_videos": 10
  }
}

def __init__(self, sessdata: str = "", bili_jct: str = "", buvid3: str = "", dedeuserid: str = "", all_cookies: dict = None):
    """
    初始化 API 客户端

    Args:
        sessdata: SESSDATA cookie
        bili_jct: bili_jct cookie
        buvid3: buvid3 cookie
        dedeuserid: DedeUserID cookie
        all_cookies: 所有 cookies 字典（可选，直接设置全部 cookies）
    """
    self.session = requests.Session()
    self.session.headers.update({
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        "Referer": "https://www.bilibili.com",
    })

    # 如果提供了全部 cookies，直接设置
    if all_cookies:
        for key, value in all_cookies.items():
            self.session.cookies.set(key, value, domain=".bilibili.com")
    else:
        # 设置单独的 cookies
        if sessdata:
            self.session.cookies.set("SESSDATA", sessdata, domain=".bilibili.com")
        if bili_jct:
            self.session.cookies.set("bili_jct", bili_jct, domain=".bilibili.com")
        if buvid3:
            self.session.cookies.set("buvid3", buvid3, domain=".bilibili.com")
        if dedeuserid:
            self.session.cookies.set("DedeUserID", dedeuserid, domain=".bilibili.com")

def generate_video_summary_from_subtitle(api_key: str, model: str, title: str, subtitle_text: str) -> dict:
    """
    使用 OpenRouter LLM 根据字幕生成视频总结（模拟B站AI总结格式）

    Args:
        api_key: OpenRouter API Key
        model: 模型名称
        title: 视频标题
        subtitle_text: 字幕纯文本

    Returns:
        包含 summary 和 outline 的字典
    """
    if not subtitle_text or not api_key:
        return {"summary": "", "outline": []}

    # 限制字幕长度，避免超出 token 限制
    max_chars = 8000
    if len(subtitle_text) > max_chars:
        subtitle_text = subtitle_text[:max_chars] + "..."

    prompt = f"""你是一位专业的视频内容分析师。请根据以下视频字幕，生成一份结构化的视频总结。

视频标题：{title}

视频字幕：
{subtitle_text}

请按照以下JSON格式输出（直接输出JSON，不要加任何其他内容）：
{{
    "summary": "一段100字以内的视频内容概述，概括视频的主要内容和核心观点",
    "outline": [
        {{
            "title": "第一部分标题",
            "part_outline": [
                {{"content": "要点1"}},
                {{"content": "要点2"}}
            ]
        }},
        {{
            "title": "第二部分标题",
            "part_outline": [
                {{"content": "要点1"}},
                {{"content": "要点2"}}
            ]
        }}
    ]
}}

要求：
1. summary 要简洁精炼，抓住视频核心内容
2. outline 按照视频内容的逻辑结构分为2-4个部分
3. 每个部分包含2-3个关键要点
4. 语言要简洁明了，直接陈述内容
5. 只输出JSON，不要有任何其他文字"""

    result = call_openrouter(api_key, model, prompt, max_tokens=1000)

def generate_video_summary_from_subtitle(api_key: str, model: str, title: str, subtitle_text: str) -> dict:
    """
    使用 OpenRouter LLM 根据字幕生成视频总结（模拟B站AI总结格式）

    Args:
        api_key: OpenRouter API Key
        model: 模型名称
        title: 视频标题
        subtitle_text: 字幕纯文本

    Returns:
        包含 summary 和 outline 的字典
    """
    if not subtitle_text or not api_key:
        return {"summary": "", "outline": []}

    # 限制字幕长度，避免超出 token 限制
    max_chars = 8000
    if len(subtitle_text) > max_chars:
        subtitle_text = subtitle_text[:max_chars] + "..."

    prompt = f"""你是一位专业的视频内容分析师。请根据以下视频字幕，生成一份结构化的视频总结。

视频标题：{title}

视频字幕：
{subtitle_text}

请按照以下JSON格式输出（直接输出JSON，不要加任何其他内容）：
{{
    "summary": "一段100字以内的视频内容概述，概括视频的主要内容和核心观点",
    "outline": [
        {{
            "title": "第一部分标题",
            "part_outline": [
                {{"content": "要点1"}},
                {{"content": "要点2"}}
            ]
        }},
        {{
            "title": "第二部分标题",
            "part_outline": [
                {{"content": "要点1"}},
                {{"content": "要点2"}}
            ]
        }}
    ]
}}

要求：
1. summary 要简洁精炼，抓住视频核心内容
2. outline 按照视频内容的逻辑结构分为2-4个部分
3. 每个部分包含2-3个关键要点
4. 语言要简洁明了，直接陈述内容
5. 只输出JSON，不要有任何其他文字"""

    result = call_openrouter(api_key, model, prompt, max_tokens=1000)

    if not result:
        return {"summary": "", "outline": []}

    # 解析 JSON 结果
    try:
        # 清理 markdown 代码块包裹
        clean_result = result.strip()
        if clean_result.startswith("```"):
            # 移除 ```json 或 ``` 开头
            lines = clean_result.split('\n')
            if lines[0].startswith("```"):
                lines = lines[1:]  # 移除第一行
            if lines and lines[-1].strip() == "```":
                lines = lines[:-1]  # 移除最后一行
            clean_result = '\n'.join(lines)

        # 尝试提取 JSON 部分（处理可能的额外文本）
        json_start = clean_result.find('{')
        json_end = clean_result.rfind('}') + 1
        if json_start >= 0 and json_end > json_start:
            json_str = clean_result[json_start:json_end]
            data = json.loads(json_str)
            return {
                "summary": data.get("summary", ""),
                "outline": data.get("outline", [])
            }
    except json.JSONDecodeError:
        # JSON 解析失败，尝试从不完整的 JSON 中提取 summary（静默处理）
        summary = _extract_summary_from_incomplete_json(result)
        if summary:
            return {"summary": summary, "outline": []}

    # 如果 JSON 解析失败，尝试从文本中提取有用信息
    summary = _extract_summary_from_incomplete_json(result)
    if summary:
        return {"summary": summary, "outline": []}

    # 如果是纯文本（不是 JSON 格式），可以作为摘要使用
    if not result.strip().startswith('{') and not result.strip().startswith('```'):
        return {"summary": result[:300].strip() if result else "", "outline": []}

    return {"summary": "", "outline": []}

def generate_ai_comment(api_key: str, model: str, video_info: dict) -> tuple[str, str]:
    """
    使用 OpenRouter LLM 生成 AI 点评和运营爆款分析

    Args:
        api_key: OpenRouter API Key
        model: 模型名称
        video_info: 视频信息字典

    Returns:
        (ai_comment, viral_analysis) 元组
    """
    title = video_info["title"]
    stat = video_info["stat"]
    ai_summary = video_info.get("ai_summary", "")
    like_rate = video_info.get("like_rate", 0)

    prompt = f"""你是一位B站内容分析专家。请根据以下视频信息，生成两段简短的分析：

视频标题：{title}
播放量：{format_number(stat['view'])}
点赞数：{format_number(stat['like'])}
收藏数：{format_number(stat['favorite'])}
硬币数：{format_number(stat['coin'])}
弹幕数：{stat['danmaku']:,}
评论数：{stat['reply']:,}
分享数：{stat['share']:,}
点赞率：{like_rate:.1f}%
B站AI总结：{ai_summary if ai_summary else '暂无'}

请生成：
1. **AI点评**（1-2句话，分析视频为何受欢迎，内容特点，或值得关注的地方）
2. **运营爆款分析**（使用固定格式：**爆款因素**：xxx **数据亮点**：xxx **成功关键**：xxx）

要求：
- 语言简洁有力，像专业的内容运营分析
- 每个部分不超过50字
- 直接输出内容，不要加额外的标题或序号

输出格式（严格遵守）：
AI点评：[你的点评内容]
运营分析：**爆款因素**：[内容] **数据亮点**：[内容] **成功关键**：[内容]"""

    # 调用 OpenRouter API
    result = call_openrouter(api_key, model, prompt)

    if not result:
        return "", ""

    # 解析结果
    ai_comment = ""
    viral_analysis = ""

    lines = result.split("\n")
    for line in lines:
        line = line.strip()
        if not line:
            continue
        # 匹配 AI点评
        if "AI点评" in line:
            parts = line.split("：", 1) if "：" in line else line.split(":", 1)
            if len(parts) > 1:
                ai_comment = parts[1].strip()
        # 匹配运营分析
        elif "运营分析" in line or "**爆款因素**" in line:
            if "：" in line:
                parts = line.split("：", 1)
                viral_analysis = parts[1].strip() if len(parts) > 1 else line
            elif ":" in line:
                parts = line.split(":", 1)
                viral_analysis = parts[1].strip() if len(parts) > 1 else line
            else:
                viral_analysis = line.strip()

    # 如果解析失败，尝试直接使用整个返回作为点评
    if not ai_comment and not viral_analysis and result:
        ai_comment = result.split("\n")[0][:100] if result else ""

    return ai_comment, viral_analysis

